    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG eller ICO. För animerade filer exporteras endast den första bildrutan. Metadata kopieras inte.",
    "Transparent areas become white. Animated images use only their first frame.": "Genomskinliga områden blir vita. För animerade bilder används endast den första bildrutan.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG och ICO. För animerade filer exporteras endast den första bildrutan. Utdata upp till 40 megapixlar.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Konvertera vanliga bildformat till JPG, PNG eller WebP direkt på enheten. Upp till 20 filer.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Lägg till upp till 20 bilder. Ingen fast gräns för filstorlek; 20 megapixlar per bild. Stora batcher begränsas av enhetens minne.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Bilderna har konverterats. Animerade filer blir till en stillbild; metadata kopieras inte.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Vissa filer hoppades över. Använd ett format som stöds och håll dig inom gränserna för verktyget.",
    "This image could not be decoded by your browser. Try another file or browser.": "Bilden kunde inte avkodas av webbläsaren. Prova en annan fil eller webbläsare.",
    "Choose a supported image format.": "Välj ett bildformat som stöds.",
    "The browser does not support the selected output format.": "Webbläsaren saknar stöd för det valda utdataformatet.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Upp till 20 bilder · 20 megapixlar per bild · ingen fast gräns för filstorlek. Stora batcher begränsas av enhetens minne.",
    "Choose up to 20 images.": "Välj upp till 20 bilder.",
    "AVIF and some HEIC files may depend on browser support.": "För AVIF och vissa HEIC-filer krävs stöd i webbläsaren.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "För AVIF- och vissa HEIC-filer krävs stöd i webbläsaren. Animerade GIF-, APNG- och WebP-filer blir till en stillbild. SVG-filer rastreras och konverteras inte till redigerbar vektorgrafik. Metadata kopieras inte.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "För TIFF-filer med flera sidor används endast den första sidan. Vissa varianter av TIFF-komprimering kanske inte kan avkodas.",
    "Choose a DOCX, XLSX or PPTX file": "Välj en DOCX-, XLSX- eller PPTX-fil.",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Filerna stannar på din enhet. Gränser: 100 MB för indata, 200 MB för expanderad data och 5 000 paketdelar.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Detta komprimerar om Office-paketet på ett säkert sätt utan att ändra innehållet. Inbäddade foton komprimeras inte om, så filstorleken kanske inte minskar. Signerade, krypterade eller äldre Office-filer samt filer med makron stöds inte. Behåll originalfilen.",
    "Try to reduce file size": "Försök att minska filstorleken.",
    "Processing runs locally in this browser. No upload.": "Bearbetningen sker lokalt i webbläsaren. Ingen uppladdning.",
    "Recompressing the Office package on your device…": "Komprimerar om Office-paketet på din enhet...",
    "This package is already compact. No smaller download was created.": "Paketet är redan kompakt. Ingen mindre fil skapades för nedladdning.",
    "A smaller copy is ready. Compare it and keep your original.": "En mindre kopia är klar. Jämför den med originalet och behåll originalfilen.",
    "The file could not be safely recompressed. Your original has not changed.": "Filen kunde inte komprimeras om på ett säkert sätt. Originalfilen har inte ändrats.",
    "Processing canceled. Your original file is unchanged.": "Bearbetningen avbröts. Originalfilen är oförändrad.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Välj en modern DOCX-, XLSX- eller PPTX-fil.",
    "This file is larger than the 100 MB local processing limit.": "Filen är större än gränsen på 100 MB för lokal bearbetning.",
    "The expanded package exceeds the 200 MB local processing limit.": "Det expanderade paketet överskrider gränsen på 200 MB för lokal bearbetning.",
    "Encrypted Office packages are not supported.": "Krypterade Office-paket stöds inte.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "Signerade Office-filer eller filer med makron stöds inte, för att undvika att ogiltigförklara signaturer eller makron.",
    "The selected file is not a valid modern Office document of that type.": "Den valda filen är inte ett giltigt modernt Office-dokument av den typen.",
