    "Check the selected file and settings, then try again.": "Kontrollera vald fil och inställningar och försök sedan igen.",
    "Up to 200 files; 100 MB total or expanded. ZIP64 and password-protected files are not supported. Large archives use device memory; a computer is recommended.": "Upp till 200 filer; totalt 100 MB (även uppackat). ZIP64-filer och lösenordsskyddade filer stöds inte. Stora arkiv använder enhetens minne; användning av dator rekommenderas.",
    "Convert / trim": "Konvertera/beskär",
    "Estimate only, not a loan offer. Fees, taxes, insurance and lender terms are not included.": "Endast en uppskattning, inte ett låneerbjudande. Avgifter, skatter, försäkring och långivarens villkor ingår inte.",
    "Illustration only; actual returns vary and are not guaranteed. Taxes, inflation and fees are excluded.": "Endast för illustration; faktisk avkastning varierar och garanteras inte. Skatter, inflation och avgifter är exkluderade.",
    "Website design,1,500\nHosting,12,10": "Webbdesign,1 500\nWebbhotell,12,10",
