    "Enter content, then preview it or open your browser’s print dialog.": "Ange innehåll och förhandsgranska eller öppna utskriftsdialogen.",
    "Preview ready. Check the page before printing.": "Förhandsgranskning klar. Kontrollera sidan före utskrift.",
    "Print dialog opened. Choose Save as PDF to create the file.": "Utskriftsdialogrutan har öppnats. Välj ”Spara som PDF” för att skapa filen.",
    "The browser creates the PDF. Paper size, margins and headers are set in the print dialog.": "Webbläsaren skapar PDF-filen. Pappersstorlek, marginaler och sidhuvuden ställs in i utskriftsdialogrutan.",
    "For safety, scripts, styles, images, links, forms and external content are removed. This tool prints simple text and tables; it does not convert a website URL.": "Av säkerhetsskäl tas skript, formatmallar, bilder, länkar, formulär och externt innehåll bort. Verktyget skapar en enkel text- och tabellversion; det konverterar inte webbadresser.",
    "HTML content is limited to 250,000 characters. Website URLs are not fetched.": "HTML-innehållet begränsas till 250 000 tecken. Webbadresser hämtas inte.",
    "Choose a PDF to convert to PDF/A": "Välj en PDF att konvertera till PDF/A",
    "PDF/A-1b makes a flattened image copy of every page. Text is not searchable or selectable. Forms, links, existing signatures, metadata and accessibility structure are not retained. Keep your original.": "PDF/A-1b skapar en plattad bildkopia av varje sida. Texten går inte att söka i eller markera. Formulär, länkar, befintliga signaturer, metadata och tillgänglighetsstruktur bevaras inte. Spara originalet.",
    "This is a visual archival copy, not an accessibility or electronic-signature copy. The browser does not run veraPDF on each file. Validate the download before relying on archival compliance.": "Detta är en visuell arkivkopia, inte en kopia avsedd för tillgänglighet eller elektronisk signering. Webbläsaren kör inte veraPDF på varje fil. Validera nedladdningen innan du förlitar dig på att den uppfyller arkiveringskraven.",
    "Output resolution": "Utdatans upplösning",
    "I understand that this creates an image-only copy; my original file will not be changed.": "Jag förstår att en kopia med enbart bilder skapas; originalfilen ändras inte.",
