    "Rendering page": "Återger sida",
    "Preparing PDF/A file…": "Förbereder PDF/A-fil…",
    "PDF/A-1b image copy is ready. The browser confirmed that it opens and has the expected number of pages; this file was not individually validated with veraPDF. Verify it before relying on archival compliance.": "PDF/A-1b-bildkopian är klar. Webbläsaren har bekräftat att filen går att öppna och har förväntat antal sidor; filen har inte validerats individuellt med veraPDF. Kontrollera filen innan du förlitar dig på att den uppfyller arkiveringskraven.",
    "This PDF could not be converted to a PDF/A copy. The original file is unchanged.": "Denna PDF kunde inte konverteras till en PDF/A-kopia. Originalfilen är oförändrad.",
    "This PDF is processed on your device and is not uploaded. A computer is recommended for this memory-intensive conversion.": "Denna PDF bearbetas på din enhet och laddas inte upp. Vi rekommenderar att du använder en dator för denna minneskrävande konvertering.",
    "Visual edits flatten modified pages; searchable text on them is lost. Limit: 50 MB, 100 pages, 40 MP. A computer is recommended.": "Visuella ändringar gör att modifierade sidor slås samman till en enda bild; sökbar text på dessa sidor går förlorad. Gränser: 50 MB, 100 sidor, 40 MP. Vi rekommenderar att du använder en dator.",
    "Edit text or image": "Redigera text eller bild",
    "Drag over the area to replace, then add text or a PNG/JPEG image. A solid background hides the old content; it may not match the page. Modified pages are flattened and lose searchable text.": "Markera området som ska ersättas genom att dra över det, och lägg sedan till text eller en PNG-/JPEG-bild. En heltäckande bakgrund döljer det gamla innehållet; den kanske inte matchar sidans utseende. Modifierade sidor slås samman till en bild och förlorar sökbar text.",
