    "Choose a file": "Välj en fil",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Office-filer stannar kvar på din enhet. Layout, formler, diagram, animeringar, typsnitt och sidbrytningar kan komma att ändras. Funktionen \"Office till PDF\" öppnar webbläsarens utskriftsdialogruta. Använd en dator för stora filer.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "Funktionen \"PDF till Excel\" identifierar rader utifrån markerbar text; den återskapar inte formler eller tabeller. \"PDF till PowerPoint\" skapar bilder av sidorna. Skannade PDF-filer kräver OCR-behandling först.",
