      "intro": "Det är enkelt att ta bort dubblettrader; det viktiga är att avgöra vad som faktiskt räknas som en ”dubblett”. Upprepade e-postadresser, upprepade hela rader och upprepade kombinationer av namn och datum utgör olika regler. Fastställ regeln och skydda originalet innan du tar bort något.",
